import{_ as l,a0 as i,w as r,s as o,I as n,x as t,a1 as a,A as p,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"計算機實驗室之樹莓派：課程 4 OK04 | LCTT x X-CMD","titleTemplate":false,"description":"計算機實驗室之樹莓派：課程 4 OK04 | LCTT (201902) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"計算機實驗室之樹莓派：課程 4 OK04 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"計算機實驗室之樹莓派：課程 4 OK04 | LCTT (201902) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201902/20120204 Computer Laboratory - Raspberry Pi- Lesson 4 OK04","title":"計算機實驗室之樹莓派：課程 4 OK04","tag":"201902","desc":""},"relativePath":"201902/20120204 Computer Laboratory - Raspberry Pi- Lesson 4 OK04.md","filePath":"[post].md"}'),c={name:"201902/20120204 Computer Laboratory - Raspberry Pi- Lesson 4 OK04.md"};function u(b,s,h,m,g,k){const e=i("Link");return r(),o("div",null,[s[21]||(s[21]=n("h1",{id:"計算機實驗室之樹莓派-課程-4-ok04",tabindex:"-1"},[t("計算機實驗室之樹莓派：課程 4 OK04 "),n("a",{class:"header-anchor",href:"#計算機實驗室之樹莓派-課程-4-ok04","aria-label":"Permalink to “計算機實驗室之樹莓派：課程 4 OK04”"},"​")],-1)),n("p",null,[s[1]||(s[1]=t("OK04 課程在 OK03 的基礎上進行構建，它教你如何使用定時器讓 OK 或 ACT LED 燈按精確的時間間隔來閃爍。假設你已經有了 ",-1)),a(e,{href:"https://linux.cn/article-10519-1.html"},{default:p(()=>[...s[0]||(s[0]=[t("課程 3：OK03",-1)])]),_:1}),s[2]||(s[2]=t(" 的操作系統，我們將以它為基礎來構建。",-1))]),s[22]||(s[22]=d(`<h3 id="_1、一個新設備" tabindex="-1">1、一個新設備 <a class="header-anchor" href="#_1、一個新設備" aria-label="Permalink to “1、一個新設備”">​</a></h3><blockquote><p>定時器是樹莓派保持時間的唯一方法。大多數計算機都有一個電池供電的時鐘，這樣當計算機關機後仍然能保持時間。</p></blockquote><p>到目前為止，我們僅看了樹莓派硬件的一小部分，即 GPIO 控制器。我只是簡單地告訴你做什麼，然後它會發生什麼事情。現在，我們繼續看定時器，並繼續帶你去了解它的工作原理。</p><p>和 GPIO 控制器一樣，定時器也有地址。在本案例中，定時器的基地址在 20003000<sub>16</sub>。閲讀手冊我們可以找到下面的表：</p><p>表 1.1 GPIO 控制器寄存器</p><div class="table-wrap"><table><thead><tr><th>地址</th><th>大小 / 字節</th><th>名字</th><th>描述</th><th>讀或寫</th></tr></thead><tbody><tr><td>20003000</td><td>4</td><td>Control / Status</td><td>用於控制和清除定時器通道比較器匹配的寄存器</td><td>RW</td></tr><tr><td>20003004</td><td>8</td><td>Counter</td><td>按 1 MHz 的頻率遞增的計數器</td><td>R</td></tr><tr><td>2000300C</td><td>4</td><td>Compare 0</td><td>0 號比較器寄存器</td><td>RW</td></tr><tr><td>20003010</td><td>4</td><td>Compare 1</td><td>1 號比較器寄存器</td><td>RW</td></tr><tr><td>20003014</td><td>4</td><td>Compare 2</td><td>2 號比較器寄存器</td><td>RW</td></tr><tr><td>20003018</td><td>4</td><td>Compare 3</td><td>3 號比較器寄存器</td><td>RW</td></tr></tbody></table></div><p><img src="https://www.cl.cam.ac.uk/projects/raspberrypi/tutorials/os/images/systemTimer.png" alt="Flowchart of the system timer&#39;s operation"></p><p>這個表只告訴我們一部分內容，在手冊中描述了更多的字段。手冊上解釋説，定時器本質上是按每微秒將計數器遞增 1 的方式來運行。每次它是這樣做的，它將計數器的低 32 位（4 字節）與 4 個比較器寄存器進行比較，如果匹配它們中的任何一個，它更新 <code>Control/Status</code> 以反映出其中有一個是匹配的。</p><p>關於<ruby>位<rt>bit</rt></ruby>、<ruby>字節<rt>byte</rt></ruby>、<ruby>位字段<rt>bit field</rt></ruby>、以及數據大小的更多內容如下：</p><blockquote><p>一個位是一個單個的二進制數的名稱。你可能還記得，一個單個的二進制數既可能是一個 1，也可能是一個 0。</p><p>一個字節是一個 8 位集合的名稱。由於每個位可能是 1 或 0 這兩個值的其中之一，因此，一個字節有 2^8 = 256 個不同的可能值。我們一般解釋一個字節為一個介於 0 到 255（含）之間的二進制數。</p><p><img src="https://www.cl.cam.ac.uk/projects/raspberrypi/tutorials/os/images/gpioControllerFunctionSelect.png" alt="Diagram of GPIO function select controller register 0."></p><p>一個位字段是解釋二進制的另一種方式。二進制可以解釋為許多不同的東西，而不僅僅是一個數字。一個位字段可以將二進制看做為一系列的 1（開） 或 0（關）的開關。對於每個小開關，我們都有一個意義，我們可以使用它們去控制一些東西。我們已經遇到了 GPIO 控制器使用的位字段，使用它設置一個針腳的開或關。位為 1 時 GPIO 針腳將準確地打開或關閉。有時我們需要更多的選項，而不僅僅是開或關，因此我們將幾個開關組合到一起，比如 GPIO 控制器的函數設置（如上圖），每 3 位為一組控制一個 GPIO 針腳的函數。</p></blockquote><p>我們的目標是實現一個函數，這個函數能夠以一個時間數量為輸入來調用它，這個輸入的時間數量將作為等待的時間，然後返回。想一想如何去做，想想我們都擁有什麼。</p><p>我認為這將有兩個選擇：</p><ol><li>從計數器中讀取一個值，然後保持分支返回到相同的代碼，直到計數器的等待時間數量大於它。</li><li>從計數器中讀取一個值，加上要等待的時間數量，將它保存到比較器寄存器，然後保持分支返回到相同的代碼處，直到 <code>Control / Status</code> 寄存器更新。</li></ol><p>這兩種策略都工作的很好，但在本教程中，我們將只實現第一個。原因是比較器寄存器更容易出錯，因為在增加等待時間並保存它到比較器的寄存器期間，計數器可能已經增加了，並因此可能會不匹配。如果請求的是 1 微秒（或更糟糕的情況是 0 微秒）的等待，這樣可能導致非常長的意外延遲。</p><blockquote><p>像這樣存在被稱為“併發問題”的問題，並且幾乎無法解決。</p></blockquote><h3 id="_2、實現" tabindex="-1">2、實現 <a class="header-anchor" href="#_2、實現" aria-label="Permalink to “2、實現”">​</a></h3><p>我將把這個創建完美的等待方法的挑戰基本留給你。我建議你將所有與定時器相關的代碼都放在一個名為 <code>systemTimer.s</code> 的文件中（理由很明顯）。關於這個方法的複雜部分是，計數器是一個 8 字節值，而每個寄存器僅能保存 4 字節。所以，計數器值將分到 2 個寄存器中。</p><blockquote><p>大型的操作系統通常使用等待函數來抓住機會在後台執行任務。</p></blockquote><p>下列的代碼塊是一個示例。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ldrd r0,r1,[r2,#4]</span></span></code></pre></div><blockquote><p><code>ldrd regLow,regHigh,[src,#val]</code> 從 <code>src</code> 中的數加上 <code>val</code> 之和的地址加載 8 字節到寄存器 <code>regLow</code> 和 <code>regHigh</code> 中。</p></blockquote><p>上面的代碼中你可以發現一個很有用的指令是 <code>ldrd</code>。它加載 8 字節的內存到兩個寄存器中。在本案例中，這 8 字節內存從寄存器 <code>r2</code> 中的地址 + 4 開始，將被複制進寄存器 <code>r0</code> 和 <code>r1</code>。這種安排的稍微複雜之處在於 <code>r1</code> 實際上只持有了高位 4 字節。換句話説就是，如果如果計數器的值是 999,999,999,999<sub>10</sub> = 1110100011010100101001010000111111111111<sub>2</sub> ，那麼寄存器 <code>r1</code> 中只有 11101000<sub>2</sub>，而寄存器 <code>r0</code> 中則是 11010100101001010000111111111111<sub>2</sub>。</p><p>實現它的更明智的方式應該是，去計算當前計數器值與來自方法啓動後的那一個值的差，然後將它與要求的等待時間數量進行比較。除非恰好你希望的等待時間是佔用 8 字節的，否則上面示例中寄存器 <code>r1</code> 中的值將會丟棄，而計數器僅需要使用低位 4 字節。</p><p>當等待開始時，你應該總是確保使用大於比較，而不是使用等於比較，因為如果你嘗試去等待一個時間，而這個時間正好等於方法開始的時間與結束的時間之差，那麼你就錯過這個值而永遠等待下去。</p><p>如果你不明白如何編寫等待函數的代碼，可以參考下面的指南。</p><blockquote><p>借鑑 GPIO 控制器的創意，第一個函數我們應該去寫如何取得系統定時器的地址。示例如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.globl GetSystemTimerBase</span></span>
<span class="line"><span>GetSystemTimerBase:</span></span>
<span class="line"><span>ldr r0,=0x20003000</span></span>
<span class="line"><span>mov pc,lr</span></span></code></pre></div><p>另一個被證明非常有用的函數是返回在寄存器 <code>r0</code> 和 <code>r1</code> 中的當前計數器值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.globl GetTimeStamp</span></span>
<span class="line"><span>GetTimeStamp:</span></span>
<span class="line"><span>push {lr}</span></span>
<span class="line"><span>bl GetSystemTimerBase</span></span>
<span class="line"><span>ldrd r0,r1,[r0,#4]</span></span>
<span class="line"><span>pop {pc}</span></span></code></pre></div><p>這個函數簡單地使用了 <code>GetSystemTimerBase</code> 函數，並像我們前面學過的那樣，使用 <code>ldrd</code> 去加載當前計數器值。</p><p>現在，我們可以去寫我們的等待方法的代碼了。首先，在該方法啓動後，我們需要知道計數器值，我們可以使用 <code>GetTimeStamp</code> 來取得。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>delay .req r2</span></span>
<span class="line"><span>mov delay,r0</span></span>
<span class="line"><span>push {lr}</span></span>
<span class="line"><span>bl GetTimeStamp</span></span>
<span class="line"><span>start .req r3</span></span>
<span class="line"><span>mov start,r0</span></span></code></pre></div><p>這個代碼複製了我們的方法的輸入，將延遲時間的數量放到寄存器 <code>r2</code> 中，然後調用 <code>GetTimeStamp</code>，這個函數將會返回寄存器 <code>r0</code> 和 <code>r1</code> 中的當前計數器值。接着複製計數器值的低位 4 字節到寄存器 <code>r3</code> 中。</p><p>接下來，我們需要計算當前計數器值與讀入的值的差，然後持續這樣做，直到它們的差至少是 <code>delay</code> 的大小為止。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>loop$:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>bl GetTimeStamp</span></span>
<span class="line"><span>elapsed .req r1</span></span>
<span class="line"><span>sub elapsed,r0,start</span></span>
<span class="line"><span>cmp elapsed,delay</span></span>
<span class="line"><span>.unreq elapsed</span></span>
<span class="line"><span>bls loop$</span></span></code></pre></div><p>這個代碼將一直等待，一直到等待到傳遞給它的時間數量為止。它從計數器中讀取數值，減去最初從計數器中讀取的值，然後與要求的延遲時間進行比較。如果過去的時間數量小於要求的延遲，它切換回 <code>loop$</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.unreq delay</span></span>
<span class="line"><span>.unreq start</span></span>
<span class="line"><span>pop {pc}</span></span></code></pre></div><p>代碼完成後，函數返回。</p></blockquote><h3 id="_3、另一個閃燈程序" tabindex="-1">3、另一個閃燈程序 <a class="header-anchor" href="#_3、另一個閃燈程序" aria-label="Permalink to “3、另一個閃燈程序”">​</a></h3><p>你一旦明白了等待函數的工作原理，修改 <code>main.s</code> 去使用它。修改各處 <code>r0</code> 的等待設置值為某個很大的數量（記住它的單位是微秒），然後在樹莓派上測試。如果函數不能正常工作，請查看我們的排錯頁面。</p>`,28)),n("p",null,[s[4]||(s[4]=t("如果正常工作，恭喜你學會控制另一個設備了，會使用它，則時間由你控制。在下一節課程中，我們將完成 OK 系列課程的最後一節 ",-1)),a(e,{href:"https://www.cl.cam.ac.uk/projects/raspberrypi/tutorials/os/ok05.html"},{default:p(()=>[...s[3]||(s[3]=[t("課程 5：OK05",-1)])]),_:1}),s[5]||(s[5]=t("，我們將使用我們已經學習過的知識讓 LED 按我們的模式進行閃爍。",-1))]),s[23]||(s[23]=n("hr",null,null,-1)),n("p",null,[s[7]||(s[7]=t("via: ",-1)),a(e,{href:"https://www.cl.cam.ac.uk/projects/raspberrypi/tutorials/os/ok04.html"},{default:p(()=>[...s[6]||(s[6]=[t("https://www.cl.cam.ac.uk/projects/raspberrypi/tutorials/os/ok04.html",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=t("作者：",-1)),a(e,{href:"http://www.cl.cam.ac.uk/~rdm34"},{default:p(()=>[...s[8]||(s[8]=[t("Robert Mullins",-1)])]),_:1}),s[13]||(s[13]=t(" 選題：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[9]||(s[9]=[t("lujun9972",-1)])]),_:1}),s[14]||(s[14]=t(" 譯者：",-1)),a(e,{href:"https://github.com/qhwdw"},{default:p(()=>[...s[10]||(s[10]=[t("qhwdw",-1)])]),_:1}),s[15]||(s[15]=t(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[11]||(s[11]=[t("wxy",-1)])]),_:1})]),n("p",null,[s[18]||(s[18]=t("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[16]||(s[16]=[t("LCTT",-1)])]),_:1}),s[19]||(s[19]=t(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:p(()=>[...s[17]||(s[17]=[t("Linux中國",-1)])]),_:1}),s[20]||(s[20]=t(" 榮譽推出",-1))])])}const T=l(c,[["render",u]]);export{C as __pageData,T as default};
